        # two rows was the wrong one.
        self.assertIn("answers GET https://app.example.com/api/orders/1",
                      self.refusals["wrong_request"])
        self.assertIn("action 2 states GET https://app.example.com/api/orders/2",
                      self.refusals["wrong_request"])

